/**
 * Regenerates src/codes/*.ts from the official MyInvois SDK code tables.
 *
 *   bun run scripts/generate-codes.ts
 *
 * Each list is downloaded from https://sdk.myinvois.hasil.gov.my/files/ and
 * normalised to the interfaces in src/types (TaxType, State, Country, ...).
 * The generated files are committed; rerun this script when LHDN updates a
 * table, then review the diff and fix the matching union type in src/types
 * if new codes appeared.
 */
import { mkdirSync, writeFileSync, readFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'

const BASE = 'https://sdk.myinvois.hasil.gov.my/files'
const OUT_DIR = join(import.meta.dir, '..', 'src', 'codes')

interface ListSpec {
  /** Official file name (without .json) */
  file: string
  /** Output module name */
  module: string
  /** Exported const name */
  constName: string
  /** Element type imported from ../types */
  elementType: string
  /** JSON key holding the human-readable value */
  valueKey: string
  /** Interface property the value maps to ('description' | 'name') */
  valueProp: 'description' | 'name'
  /**
   * For lists whose union is too large for tsc to check element-by-element
   * (TS2590), the generator validates codes against these union source files
   * itself and emits a cast instead of relying on the compiler.
   */
  unionSources?: string[]
}

const LISTS: ListSpec[] = [
  { file: 'TaxTypes', module: 'tax-types', constName: 'TAX_TYPES', elementType: 'TaxType', valueKey: 'Description', valueProp: 'description' },
  { file: 'ClassificationCodes', module: 'classification-codes', constName: 'CLASSIFICATION_CODES', elementType: 'Classification', valueKey: 'Description', valueProp: 'description' },
  { file: 'StateCodes', module: 'state-codes', constName: 'STATE_CODES', elementType: 'State', valueKey: 'State', valueProp: 'name' },
  { file: 'CountryCodes', module: 'country-codes', constName: 'COUNTRY_CODES', elementType: 'Country', valueKey: 'Country', valueProp: 'name' },
  { file: 'CurrencyCodes', module: 'currency-codes', constName: 'CURRENCY_CODES', elementType: 'Currency', valueKey: 'Currency', valueProp: 'name' },
  { file: 'EInvoiceTypes', module: 'e-invoice-types', constName: 'E_INVOICE_TYPES', elementType: 'EInvoiceType', valueKey: 'Description', valueProp: 'description' },
  { file: 'PaymentMethods', module: 'payment-modes', constName: 'PAYMENT_MODES', elementType: 'PaymentMode', valueKey: 'Payment Method', valueProp: 'description' },
  { file: 'UnitTypes', module: 'unit-types', constName: 'UNIT_TYPES', elementType: 'UnitType', valueKey: 'Name', valueProp: 'name', unionSources: ['unit'] },
  { file: 'MSICSubCategoryCodes', module: 'msic-codes', constName: 'MSIC_CODES', elementType: 'MSICCode', valueKey: 'Description', valueProp: 'description', unionSources: ['msic'] },
]

/**
 * All union-member literals (`| 'CODE'`) in the .d.ts files of a types
 * subdirectory. Anchored to the `|` so apostrophes inside trailing
 * `// comments` can't desynchronise the scan.
 */
const unionLiterals = (subdir: string): Set<string> => {
  const dir = join(import.meta.dir, '..', 'src', 'types', subdir)
  const literals = new Set<string>()
  for (const f of readdirSync(dir)) {
    const source = readFileSync(join(dir, f), 'utf8')
    for (const m of source.matchAll(/[|=]\s*['"]([A-Za-z0-9]+)['"]/g)) {
      literals.add(m[1]!)
    }
  }
  return literals
}

const escape = (s: string): string =>
  s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")

const today = new Date().toISOString().split('T')[0]

mkdirSync(OUT_DIR, { recursive: true })

const indexLines: string[] = [
  '// AUTO-GENERATED by scripts/generate-codes.ts — do not edit by hand.',
  '// Runtime code lists from the official MyInvois SDK tables.',
]

for (const spec of LISTS) {
  const url = `${BASE}/${spec.file}.json`
  const res = await fetch(url)
  if (!res.ok) throw new Error(`${url} -> HTTP ${res.status}`)
  const rows = (await res.json()) as Record<string, string>[]
  if (!Array.isArray(rows) || rows.length === 0) {
    throw new Error(`${url}: empty or non-array payload`)
  }

  const seen = new Set<string>()
  const entries: string[] = []
  for (const row of rows) {
    const code = String(row.Code ?? '').trim()
    // Some official names contain hard line breaks + tabs — collapse them.
    const value = String(row[spec.valueKey] ?? '')
      .replace(/\s+/g, ' ')
      .trim()
    if (!code) throw new Error(`${spec.file}: row without Code: ${JSON.stringify(row)}`)
    if (seen.has(code)) {
      console.warn(`⚠️  ${spec.file}: duplicate code ${code} — keeping first`)
      continue
    }
    seen.add(code)
    if (spec.module === 'msic-codes') {
      const ref = String(row['MSIC Category Reference'] ?? '').trim()
      entries.push(
        `  { code: '${escape(code)}', ${spec.valueProp}: '${escape(value)}', categoryReference: '${escape(ref)}' },`,
      )
    } else {
      entries.push(
        `  { code: '${escape(code)}', ${spec.valueProp}: '${escape(value)}' },`,
      )
    }
  }

  // For huge unions tsc can't check the literal element-by-element (TS2590),
  // so validate codes against the union source files here and emit a cast.
  let declaration = `export const ${spec.constName}: readonly ${spec.elementType}[] = [`
  let close = ']'
  if (spec.unionSources) {
    const known = new Set<string>()
    for (const src of spec.unionSources) {
      for (const lit of unionLiterals(src)) known.add(lit)
    }
    const missing = [...seen].filter(code => !known.has(code))
    if (missing.length > 0) {
      throw new Error(
        `${spec.file}: ${missing.length} code(s) missing from src/types/${spec.unionSources.join(',')} unions: ${missing.join(', ')} — add them to the union types first`,
      )
    }
    declaration =
      `// tsc cannot check ${entries.length} literals against the ${spec.elementType} code union (TS2590);\n` +
      `// the generator has validated every code against the union source files instead.\n` +
      `export const ${spec.constName}: readonly ${spec.elementType}[] = [`
    close = `] as unknown as readonly ${spec.elementType}[]`
    declaration = declaration.replace(
      `: readonly ${spec.elementType}[] = [`,
      ` = [`,
    )
  }

  const header = [
    '// AUTO-GENERATED by scripts/generate-codes.ts — do not edit by hand.',
    `// Source: ${url} (fetched ${today}, ${entries.length} entries)`,
    `import type { ${spec.elementType} } from '../types'`,
    '',
  ].join('\n')

  const body = `${declaration}\n${entries.join('\n')}\n${close}\n`
  writeFileSync(join(OUT_DIR, `${spec.module}.ts`), `${header}${body}`)
  indexLines.push(`export { ${spec.constName} } from './${spec.module}'`)
  console.log(`✔ ${spec.module}.ts (${entries.length} entries)`)
}

writeFileSync(join(OUT_DIR, 'index.ts'), indexLines.join('\n') + '\n')
console.log('✔ index.ts')
